VectionMotion.customGLSL:
// @node vectionMotion
// @title Vection Motion
// @category custom
// @description Flight controller for a 5x1 rgba32f / nearest Feedback (wire its out back into state). Integrates the flight down the curving street: distance from a slowly accelerating speed (+ kick surges), the coordinated bank of the curve plus a slow 0.055 / 0.13 Hz roll swing (roll vection), a bar-locked lean, footstep bob and nod on the beat (scaled by u_beatConfidence), a small ride jitter, and a breakdown freeze (the world stops when the music drops, so a motion aftereffect makes it seem to drift backwards). Texels: 0 (clock, distance, speed, freeze) | 1 (level fast, level slow, music presence, kick surge) | 2 (camera x, camera y, unused, roll) | 3 (yaw, pitch, focus of expansion x, y as view tangents) | 4 (speed / cruise, bob, unused, unused).

// Street centre line x(z): two sines whose periods divide the wrap length, so the world tiles seamlessly
float vm_curve(float z) {
    return 22.0 * sin(z * (6.2831853 / 1200.0)) + 9.0 * sin(z * (6.2831853 / 480.0) + 1.0);
}
float vm_curveD(float z) {
    return 22.0 * (6.2831853 / 1200.0) * cos(z * (6.2831853 / 1200.0)) + 9.0 * (6.2831853 / 480.0) * cos(z * (6.2831853 / 480.0) + 1.0);
}
float vm_curveDD(float z) {
    float a = 6.2831853 / 1200.0;
    float b = 6.2831853 / 480.0;
    return -22.0 * a * a * sin(z * a) - 9.0 * b * b * sin(z * b + 1.0);
}

// Footstep: a quick dip right after the beat, springing back by the next one (0 at both ends)
float vm_step(float p) {
    float k = 6.0;
    float f = k * p * exp(1.0 - k * p);
    return f - p * k * exp(1.0 - k);
}

vec4 vectionMotion(sampler2D state, float time, float intensity, float speed, float roll, float breakdown, float music) {
    int px = int(gl_FragCoord.x);
    vec4 s0 = texelFetch(state, ivec2(0, 0), 0);
    vec4 s1 = texelFetch(state, ivec2(1, 0), 0);
    float I = clamp(intensity, 0.0, 1.5);
    float drive = clamp(music, 0.0, 2.0);
    // beat-phase couplings fade in as the beat tracker locks (1 with the metronome)
    float beatDrive = drive * clamp(u_beatConfidence, 0.0, 1.0) * smoothstep(0.25, 0.75, u_beatTrust); // x the beat clock's trust: no bob / lean on beats that are not in the music (a track change)
    bool fresh = s0.x <= 0.0 || s0.y != s0.y;
    float dt = time - s0.x;
    if (fresh || dt < 0.0 || dt > 0.25) dt = 1.0 / 60.0;   // dt = 0 when paused: hold still

    // ---- Music followers: fast and slow level, and a "music has been playing" presence ----
    float lv = u_level;
    float lf = fresh ? lv : mix(s1.x, lv, 1.0 - exp(-dt / 0.15));
    float ls = fresh ? lv : mix(s1.y, lv, 1.0 - exp(-dt / 6.0));
    float pres = fresh ? drive : mix(s1.z, drive, 1.0 - exp(-dt / (drive > s1.z ? 0.5 : 10.0)));

    // ---- Breakdown: the level falls far below its recent average -> ease the flight to a stop ----
    float ratio = lf / max(ls, 0.04);
    float fT = clamp(breakdown, 0.0, 1.0) * clamp(pres, 0.0, 1.0) * smoothstep(0.55, 0.3, ratio) * smoothstep(0.12, 0.25, ls);
    float fr = fresh ? 0.0 : mix(s0.w, fT, 1.0 - exp(-dt / (fT > s0.w ? 0.9 : 0.5)));

    // ---- Speed: slow, smooth acceleration cycles (26 s and 71 s), plus surges on the kick ----
    float cruise = 26.0 * max(speed, 0.0);
    float cyc = 0.5 - 0.5 * cos(time * 6.2831853 / 26.0);
    float phrase = 0.5 - 0.5 * cos(time * 6.2831853 / 71.0 + 1.3);
    float target = cruise * (0.62 + I * (0.55 * cyc + 0.3 * phrase));
    float surge = fresh ? 0.0 : max(s1.w * exp(-dt / 0.45), drive * u_kick);
    target = target * (1.0 - 0.95 * fr) + cruise * 0.55 * I * surge * (1.0 - fr);
    float v = fresh ? target : mix(s0.z, target, 1.0 - exp(-dt / 0.3));
    float D = mod((fresh ? 0.0 : s0.y) + v * dt, 4800.0);
    float vn = v / max(cruise, 1e-3);

    // ---- Camera path: follow the street, drift between lanes, swoop low and high ----
    float weave = 2.2 * I * sin(time * 6.2831853 / 17.0);
    float camX = vm_curve(D) + weave;
    float h = 9.5 + 4.5 * sin(time * 6.2831853 / 34.0 + 0.6);
    float bob = -0.42 * I * beatDrive * vm_step(u_beatPhase);
    // ride jitter: a small smooth shake (3-7 Hz) that grows with speed
    float jA = I * clamp(vn, 0.0, 1.6);
    vec3 jit = jA * vec3(
        0.6 * sin(time * 19.1) + 0.4 * sin(time * 31.7 + 1.1),
        0.6 * sin(time * 23.3 + 2.0) + 0.4 * sin(time * 41.3 + 0.4),
        0.6 * sin(time * 17.9 + 4.0) + 0.4 * sin(time * 29.3 + 2.6));
    float camY = h + bob + 0.06 * jit.y;
    camX += 0.06 * jit.x;

    // look toward the street 40 m ahead
    float ahead = 40.0;
    float yaw = atan(vm_curve(D + ahead) - camX, ahead);
    float pitch = -0.06 - 0.012 * (h - 9.5) - 0.03 * I * beatDrive * vm_step(u_beatPhase) + 0.0025 * jit.z;

    // ---- Roll: coordinated bank of the curve + slow swing (roll vection) + a lean on each bar ----
    float bank = atan(1.4 * v * v * vm_curveDD(D + 20.0) / 9.81);
    float rad = radians(roll) * I;
    float swing = rad * (0.72 * sin(time * 6.2831853 * 0.055) + 0.28 * sin(time * 6.2831853 * 0.13 + 2.0));
    float bar = floor(u_beatCount / 4.0 + 1e-3);
    float lean = radians(9.0) * I * beatDrive * sin(1.5707963 * (bar + smoothstep(0.0, 0.6, u_barPhase)));
    float rollA = bank + swing + lean + radians(0.3) * jit.z;

    // ---- Focus of expansion: the velocity direction in view tangents ----
    vec3 vel = normalize(vec3(vm_curveD(D), 0.0, 1.0));
    vec3 F = vec3(sin(yaw) * cos(pitch), sin(pitch), cos(yaw) * cos(pitch));
    vec3 R = normalize(cross(vec3(0.0, 1.0, 0.0), F));
    vec3 U = cross(F, R);
    float cr = cos(rollA);
    float sr = sin(rollA);
    vec3 R2 = cr * R - sr * U;
    vec3 U2 = cr * U + sr * R;
    float fz = max(dot(vel, F), 0.05);
    vec2 foe = vec2(dot(vel, R2), dot(vel, U2)) / fz;

    if (px == 0) return vec4(time, D, v, fr);
    if (px == 1) return vec4(lf, ls, pres, surge);
    if (px == 2) return vec4(camX, camY, 0.0, rollA);
    if (px == 3) return vec4(yaw, pitch, foe);
    return vec4(vn, bob, 0.0, 0.0);
}

VectionCity.customGLSL:
// @node vectionCity
// @title Vection City
// @category custom
// @description Analytic ray tracer of an endless curving street canyon at dusk, seen from the camera in the Vection Motion state texture. Two rows of buildings per side (block DDA, front and side faces), cross streets, a wet street with mirror puddles that reflect the facades and lamps, lamp halos and light pools, parallax motes on 10 depth planes, dusk sky with sun, streaky clouds and height fog. Dense lit-window grids put high-contrast texture in the periphery; illusion paints Fraser-Wilcox luminance sawtooth friezes (black, dark gray, white, light gray toward the viewer) on the curbs, shop fronts and rooflines so they seem to stream toward you even when the flight stops. palette 0 ember dusk, 1 blue hour, 2 neon night. pulse (x u_beatConfidence) / bass (0 when silent) swell the lamps and windows. Returns HDR color, alpha = nearness (for motion blur).
float vc_curve(float z) {
    return 22.0 * sin(z * (6.2831853 / 1200.0)) + 9.0 * sin(z * (6.2831853 / 480.0) + 1.0);
}

vec3 vc_hash3(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return vec3(v) * (1.0 / 4294967296.0);
}
vec3 vc_h3(float a, float b, float c) {
    return vc_hash3(uvec3(ivec3(floor(vec3(a, b, c))) + ivec3(65536)));
}

// Value noise, periodic with period per (in lattice units) on y
float vc_noise(vec2 p, float per) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float y0 = mod(i.y, per);
    float y1 = mod(i.y + 1.0, per);
    float a = vc_h3(i.x, y0, 3.0).x;
    float b = vc_h3(i.x + 1.0, y0, 3.0).x;
    float c = vc_h3(i.x, y1, 3.0).x;
    float d = vc_h3(i.x + 1.0, y1, 3.0).x;
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Palette color k (0 zenith, 1 horizon, 2 sun, 3 window, 4 window alt, 5 lamp, 6 fog, 7 neon); pal 0 ember dusk, 1 blue hour, 2 neon night
vec3 vc_c(int k, float pal) {
    vec3 A[8] = vec3[8](vec3(0.05, 0.06, 0.19), vec3(1.0, 0.40, 0.16), vec3(1.0, 0.52, 0.22), vec3(1.0, 0.60, 0.30),
                        vec3(0.50, 0.72, 1.0), vec3(1.0, 0.66, 0.36), vec3(0.27, 0.17, 0.22), vec3(0.30, 0.85, 1.0));
    vec3 B[8] = vec3[8](vec3(0.025, 0.05, 0.17), vec3(0.46, 0.40, 0.80), vec3(0.95, 0.55, 0.62), vec3(1.0, 0.74, 0.46),
                        vec3(0.55, 0.88, 1.0), vec3(0.95, 0.82, 0.62), vec3(0.19, 0.21, 0.40), vec3(1.0, 0.42, 0.80));
    vec3 C[8] = vec3[8](vec3(0.008, 0.008, 0.035), vec3(0.50, 0.10, 0.42), vec3(0.85, 0.22, 0.65), vec3(0.35, 0.85, 1.0),
                        vec3(1.0, 0.35, 0.75), vec3(0.45, 0.78, 1.0), vec3(0.12, 0.05, 0.20), vec3(1.0, 0.30, 0.60));
    float p = clamp(pal, 0.0, 2.0);
    return mix(mix(A[k], B[k], clamp(p, 0.0, 1.0)), C[k], clamp(p - 1.0, 0.0, 1.0));
}

// Block i of row (0 street front, 1 back row) on side s: x = facade offset, y = height, z = 1 for a cross street, w = seed
vec4 vc_block(float row, float s, float i) {
    if (row < 0.5) {
        float n = mod(i, 400.0);
        vec3 h = vc_h3(n, s + 2.0, 7.0);
        float gap = step(vc_h3(n, 9.0, 3.0).x, 0.12);
        return vec4(14.0 + floor(h.x * 4.0) * 1.6, 24.0 + 78.0 * h.y * h.y, gap, h.z);
    }
    float n = mod(i, 200.0);
    vec3 h = vc_h3(n, s + 5.0, 11.0);
    return vec4(36.0 + 22.0 * h.x, 46.0 + 165.0 * h.y * h.y, step(fract(h.z * 37.0), 0.05), h.z);
}

// Nearest building hit along the ray before tmax. n = face normal, m = (row, side, block, face: 0 front / 1 side)
float vc_trace(vec3 ro, vec3 rd, float tmax, int steps0, int steps1, out vec3 n, out vec4 m) {
    float tHit = tmax;
    n = vec3(0.0, 1.0, 0.0);
    m = vec4(-1.0);
    float invz = 1.0 / max(rd.z, 1e-4);
    for (int r = 0; r < 2; r++) {
        float row = float(r);
        float L = r == 0 ? 12.0 : 24.0;
        float maxH = r == 0 ? 102.0 : 211.0;
        int steps = r == 0 ? steps0 : steps1;
        for (int si = 0; si < 2; si++) {
            float s = si == 0 ? -1.0 : 1.0;
            if (s * rd.x * invz < -0.26) continue;   // heading away faster than the street can curve
            float i = floor(ro.z / L);
            for (int k = 0; k < 64; k++) {
                if (k >= steps) break;
                float zA = max(ro.z, i * L);
                float tA = (zA - ro.z) * invz;
                if (tA >= tHit) break;
                float yA = ro.y + rd.y * tA;
                if (yA > maxH && rd.y >= 0.0) break;
                vec4 b = vc_block(row, s, i);
                if (b.z < 0.5) {
                    float c = vc_curve((i + 0.5) * L);
                    float fA = s * (ro.x + rd.x * tA - c) - b.x;
                    if (fA > 0.0) {
                        if (yA < b.y && yA > 0.0) { tHit = tA; n = vec3(0.0, 0.0, -1.0); m = vec4(row, s, i, 1.0); break; }
                    } else {
                        float sdx = s * rd.x;
                        if (sdx > 1e-6) {
                            float tc = tA - fA / sdx;
                            float tB = ((i + 1.0) * L - ro.z) * invz;
                            if (tc < tB && tc < tHit) {
                                float yc = ro.y + rd.y * tc;
                                if (yc < b.y && yc > 0.0) { tHit = tc; n = vec3(-s, 0.0, 0.0); m = vec4(row, s, i, 0.0); break; }
                            }
                        }
                    }
                }
                i += 1.0;
            }
        }
    }
    return tHit;
}

// Box [a, b] inside a unit cell, filtered over a footprint w (cell units)
float vc_box(float f, float a, float b, float w) {
    return clamp(smoothstep(a - w, a + w, f) - smoothstep(b - w, b + w, f), 0.0, 1.0);
}

// Fraser-Wilcox / Kitaoka sawtooth: along +z light gray, white, dark gray, black, so toward the
// viewer (-z) it reads black -> dark gray -> white -> light gray, the direction of illusory drift.
// w = footprint in periods; the pattern fades to its mean before it can alias.
float vc_drift(vec4 K, float x, float w) {
    float f = fract(x);
    float e = clamp(w, 0.004, 0.25);
    float v = 0.0
        + (0.72 - 0.0) * smoothstep(-e, e, f)
        + (1.0 - 0.72) * smoothstep(0.25 - e, 0.25 + e, f)
        + (0.26 - 1.0) * smoothstep(0.5 - e, 0.5 + e, f)
        + (0.0 - 0.26) * smoothstep(0.75 - e, 0.75 + e, f)
        + (0.72 - 0.0) * smoothstep(1.0 - e, 1.0 + e, f);
    float k = clamp(K.y, 0.0, 1.0) * (1.0 - smoothstep(0.12, 0.35, w));
    return mix(0.5, v, k);
}

vec3 vc_sky(vec4 K, vec3 d, vec3 ro, float time, bool clouds) {
    float y = d.y;
    vec3 c = mix(vc_c(1, K.x), vc_c(0, K.x), smoothstep(-0.02, 0.5, y));
    c = mix(c, vc_c(1, K.x) * 0.25, smoothstep(0.0, -0.25, y));
    float sd = max(dot(d, vec3(0.0, 0.0349, 0.9994)), 0.0);
    c += vc_c(2, K.x) * (0.30 * pow(sd, 8.0) + 0.9 * pow(sd, 90.0));
    c += vc_c(2, K.x) * smoothstep(0.99955, 0.9998, sd) * 12.0;
    c += vc_c(1, K.x) * 0.45 * exp(-abs(y - 0.01) * 28.0);
    if (clouds && y > 0.015) {
        vec2 cp = ro.xz + d.xz * ((900.0 - ro.y) / y) + vec2(time * 6.0, 0.0);
        vec2 q = cp * vec2(1.0 / 1600.0, 1.0 / 480.0);
        float nz = 0.55 * vc_noise(q, 10.0) + 0.3 * vc_noise(q * 2.0 + 7.3, 20.0) + 0.15 * vc_noise(q * 4.0 + 3.1, 40.0);
        float cov = smoothstep(0.48, 0.78, nz) * smoothstep(0.015, 0.08, y) * (1.0 - smoothstep(0.35, 0.8, y));
        vec3 cc = mix(vc_c(0, K.x) * 1.6 + vc_c(1, K.x) * 0.15, vc_c(2, K.x) * 0.9 + vc_c(1, K.x) * 0.4, exp(-y * 5.0) * (0.4 + 0.6 * sd));
        c = mix(c, cc, cov * 0.85);
    }
    return c;
}

// Street lamps: halo along the ray (both sides, 24 m apart)
vec3 vc_lamps(vec4 K, vec3 ro, vec3 rd, float tmax, float pix, int count) {
    vec3 acc = vec3(0.0);
    float k0 = floor((ro.z - 6.0) / 24.0) + 1.0;
    for (int j = 0; j < 16; j++) {
        if (j >= count) break;
        float z = (k0 + float(j)) * 24.0 + 6.0;
        if (z - ro.z > tmax * rd.z + 4.0) break;
        float cz = vc_curve(z);
        for (int si = 0; si < 2; si++) {
            float s = si == 0 ? -1.0 : 1.0;
            vec3 w = vec3(cz + s * 10.4, 7.6, z) - ro;
            float tc = dot(w, rd);
            if (tc <= 0.0 || tc > tmax) continue;
            float d2 = max(dot(w, w) - tc * tc, 0.0);
            float ws = max(0.22, tc * pix * 1.5);
            float ws2 = ws * ws;
            acc += (0.0484 / ws2 * exp(-d2 / ws2) * 6.0 + 0.45 / (1.0 + d2 * 1.2) + 0.04 / (1.0 + d2 * 0.05)) * exp(-tc * 0.004);
        }
    }
    return acc * vc_c(5, K.x) * K.z;
}

// Light from the nearby street lamps (pools on the street, warm wash on the lower floors)
vec3 vc_lampLight(vec4 K, vec3 p, vec3 n) {
    vec3 acc = vec3(0.0);
    float k = floor((p.z - 6.0) / 24.0 + 0.5);
    for (int j = -1; j <= 1; j++) {
        float z = (k + float(j)) * 24.0 + 6.0;
        float cz = vc_curve(z);
        for (int si = 0; si < 2; si++) {
            float s = si == 0 ? -1.0 : 1.0;
            vec3 L = vec3(cz + s * 10.4, 7.6, z) - p;
            float d2 = dot(L, L);
            float il = inversesqrt(d2);
            float ndl = max(dot(n, L) * il, 0.0);
            float spot = smoothstep(0.1, 0.8, L.y * il);
            acc += ndl * spot / (d2 + 3.0);
        }
    }
    return acc * 150.0 * vc_c(5, K.x) * K.z;
}

vec3 vc_ambient(vec4 K, vec3 n) {
    float up = 0.5 + 0.5 * n.y;
    return mix(vc_c(1, K.x) * 0.06 + vc_c(5, K.x) * 0.03, vc_c(0, K.x) * 2.2 + vc_c(1, K.x) * 0.08, up);
}

// Facade shading: lit window grid, dark glass, shop fronts, drift-pattern friezes, roofline light
vec3 vc_facade(vec4 K, vec3 p, vec3 rd, vec3 n, vec4 m, float t, float pix, float time, bool cheap) {
    float row = m.x;
    float s = m.y;
    float L = row < 0.5 ? 12.0 : 24.0;
    vec4 b = vc_block(row, s, m.z);
    float seed = b.w;
    float u;
    float per;
    if (m.w < 0.5) {
        u = p.z;
        per = row < 0.5 ? 2000.0 : 1600.0;
    } else {
        u = s * (p.x - vc_curve((m.z + 0.5) * L)) - b.x;
        per = 1e5;
    }
    float v = p.y;
    float cosv = max(abs(dot(rd, n)), 0.04);
    float fu = pix * t / cosv;
    float fv = pix * t;
    // window grid: 2.0 x 3.3 m (street row) / 2.4 x 3.6 m (back row); periods divide the wrap length
    vec2 cs = row < 0.5 ? vec2(2.0, 3.3) : vec2(2.4, 3.6);
    if (m.w < 0.5) per = row < 0.5 ? 2400.0 : 2000.0;
    vec2 g = vec2(u, v) / cs;
    vec2 cell = floor(g);
    vec2 f = fract(g);
    vec2 w = vec2(fu, fv) / cs;

    // wall albedo and light
    vec3 alb = mix(vec3(0.035, 0.036, 0.045), vec3(0.09, 0.08, 0.072), seed);
    vec3 light = vc_ambient(K, n);
    if (v < 26.0) light += vc_lampLight(K, p, n) * (1.0 - smoothstep(10.0, 26.0, v));
    vec3 col = alb * (light + vc_c(0, K.x) * 2.5 * smoothstep(0.0, 90.0, v));

    // three facade styles: punched windows, ribbon windows, glass curtain wall
    float style = fract(seed * 3.7);
    vec2 wa = vec2(0.2, 0.3);
    vec2 wb = vec2(0.8, 0.86);
    float key = cell.x;
    if (style > 0.8) { wa = vec2(0.05, 0.08); wb = vec2(0.95, 0.96); }
    else if (style > 0.55) { wa = vec2(0.0, 0.36); wb = vec2(1.0, 0.86); key = floor(cell.x / 4.0); per = per / 4.0; }
    float mull = style > 0.55 && style <= 0.8 ? 1.0 - 0.7 * vc_box(f.x, 0.0, 0.04, w.x) : 1.0;
    float mask = vc_box(f.x, wa.x, wb.x, w.x * 0.75) * vc_box(f.y, wa.y, wb.y, w.y * 0.75) * mull;
    vec3 hw = vc_h3(mod(key, per) + 17.0 * m.w, cell.y + 31.0, m.z * 3.0 + s * 101.0 + row * 7.0);
    float litP = (style > 0.8 ? 0.16 : 0.22) + 0.26 * fract(seed * 13.7);
    float lit = step(hw.x, litP);
    vec3 tint = mix(vc_c(3, K.x), vc_c(4, K.x), step(style > 0.8 ? 0.55 : 0.86, hw.z));
    float bright = 0.3 + 2.2 * hw.y * hw.y * hw.y;
    // a room: brighter toward the ceiling lights, some blinds half drawn
    float fy = clamp((f.y - wa.y) / (wb.y - wa.y), 0.0, 1.0);
    float room = (0.55 + 0.45 * fy) * mix(1.0, 0.3, step(0.72, hw.z) * step(0.55, fy));
    vec3 emis = bright * room * tint * 1.4 * K.w;
    vec3 glass = vec3(0.01, 0.012, 0.018);
    if (!cheap) {
        vec3 rr = reflect(rd, n);
        float fr = 0.04 + 0.96 * pow(1.0 - cosv, 5.0);
        // the canyon hides the low sky: only steep reflections see it, the rest mirrors dark facades
        glass += vc_sky(K, rr, p, time, false) * (0.1 + 0.55 * fr) * mix(0.12, 1.0, smoothstep(0.15, 0.6, rr.y));
    } else {
        glass += vc_c(1, K.x) * 0.04;
    }
    vec3 winCol = mix(glass, emis, lit);
    vec3 cellCol = mix(col, winCol, mask);
    // far away: the mean of the grid (no aliasing)
    float area = (wb.x - wa.x) * (wb.y - wa.y);
    vec3 meanEmis = 0.75 * 0.85 * mix(vc_c(3, K.x), vc_c(4, K.x), 0.2) * 1.4 * K.w;
    vec3 meanCol = mix(col, mix(glass, meanEmis, litP), area);
    float far = smoothstep(0.22, 0.7, max(w.x, w.y));
    col = mix(cellCol, meanCol, far);

    // ground floor: glowing shop fronts with a drift frieze above them (front faces of the street row)
    if (row < 0.5 && v < 4.4) {
        float su = fract(u / 6.0);
        float shop = vc_box(su, 0.06, 0.94, fu / 6.0) * vc_box(v / 4.4, 0.05, 0.7, fv / 4.4);
        vec3 sh = vc_h3(floor(u / 6.0), m.z, s + 40.0);
        float inner = (0.45 + 0.55 * smoothstep(0.0, 3.0, v)) * (1.0 - 0.75 * vc_box(fract(su * 3.0), 0.0, 0.05, fu / 2.0));
        vec3 shopCol = mix(vc_c(3, K.x), vc_c(7, K.x), step(0.72, sh.x)) * (0.25 + 0.9 * sh.y * sh.y) * inner * K.w;
        col = mix(col * 0.7, mix(glass, shopCol, step(0.4, sh.z)), shop);
        if (m.w < 0.5) {
            float band = vc_box(v, 3.15, 4.35, fv);
            float dpat = vc_drift(K, u / 2.4, fu / 2.4);
            col = mix(col, mix(vec3(0.9), vc_c(7, K.x), 0.25) * (0.02 + 0.95 * dpat), band * smoothstep(0.0, 0.3, K.y));
        }
    }
    // roofline: a lit cornice carrying the same drift pattern against the sky
    float top = b.y - v;
    if (top < 1.2) {
        float band = vc_box(top, 0.15, 1.05, fv);
        float dpat = m.w < 0.5 ? vc_drift(K, u / 2.0, fu / 2.0) : 0.5;
        vec3 edge = mix(vc_c(5, K.x), vc_c(7, K.x), step(0.5, fract(seed * 5.3)));
        col = mix(col, mix(vec3(0.9), edge, 0.35) * (0.03 + 1.0 * dpat), band * 0.9);
    }
    return col;
}

// Street: asphalt, lane markings, drift-pattern curbs, sidewalks, crosswalks, lamp pools
vec3 vc_street(vec4 K, vec3 q, vec3 rd, float t, float pix, out float wet) {
    float c = vc_curve(q.z);
    float u = q.x - c;
    float au = abs(u);
    float fx = pix * t;
    float fz = pix * t / max(-rd.y, 0.02);
    float gapRow = vc_block(0.0, 1.0, floor(q.z / 12.0)).z;
    float zb = fract(q.z / 12.0) * 12.0;

    float grain = vc_noise(q.xz * vec2(1.3, 0.4), 1920.0);
    vec3 alb = vec3(0.030, 0.031, 0.036) * (0.8 + 0.4 * grain);
    vec3 emit = vec3(0.0);
    // lane dashes (12 m period), center double line, edge lines
    float dash = vc_box(fract(q.z / 12.0), 0.0, 0.38, fz / 12.0);
    float lane = vc_box(au, 3.45, 3.75, fx) * dash + vc_box(au, 6.95, 7.25, fx) * dash;
    float center = vc_box(au, 0.12, 0.27, fx);
    float edgeL = vc_box(au, 10.05, 10.3, fx);
    alb = mix(alb, vec3(0.55), lane + edgeL);
    alb = mix(alb, vc_c(5, K.x) * 0.55, center);
    // crosswalk zebra where a cross street meets the avenue
    if (gapRow > 0.5) {
        float zebra = vc_box(fract(u / 1.2), 0.15, 0.6, fx / 1.2) * vc_box(zb, 0.8, 4.0, fz) * step(au, 10.0);
        alb = mix(alb, vec3(0.5), zebra);
    }
    // curb: a self-lit Fraser-Wilcox strip streaming along the street edge
    float curb = vc_box(au, 10.45, 11.25, fx) * (1.0 - gapRow);
    float dpat = vc_drift(K, q.z / 1.6, fz / 1.6);
    vec3 curbC = mix(vec3(0.8), vc_c(7, K.x), 0.2) * (0.02 + 0.85 * dpat);
    // sidewalk tiles (cross streets stay asphalt)
    if (au > 11.15 && gapRow < 0.5) {
        float joint = max(vc_box(fract(q.z / 1.5), 0.0, 0.05, fz / 1.5), vc_box(fract(au / 1.5), 0.0, 0.05, fx / 1.5));
        alb = vec3(0.075, 0.072, 0.07) * (1.0 - 0.5 * joint) * (0.85 + 0.3 * grain);
    }
    vec3 col = alb * (vc_ambient(K, vec3(0.0, 1.0, 0.0)) * 0.8 + vc_lampLight(K, q, vec3(0.0, 1.0, 0.0)));
    col = mix(col, curbC, curb);
    // wetness: mirror puddles on the road, a damp sheen elsewhere
    float pud = smoothstep(0.52, 0.64, vc_noise(q.xz * vec2(0.11, 0.05), 240.0));
    wet = mix(0.5, 1.0, pud) * (au < 10.55 || gapRow > 0.5 ? 1.0 : 0.4);
    return col;
}

vec3 vc_motes(vec4 K, vec3 ro, vec3 rd, float tmax, float pix, float dens) {
    vec3 acc = vec3(0.0);
    float S = 6.0;
    float zb = floor(ro.z / S);
    for (int j = 1; j <= 10; j++) {
        float zp = (zb + float(j)) * S;
        float t = (zp - ro.z) / max(rd.z, 1e-4);
        if (t > tmax) break;
        vec3 p = ro + rd * t;
        vec2 g = vec2(p.x - vc_curve(zp), p.y);
        if (g.y < 0.3 || g.y > 40.0) continue;
        vec2 cell = floor(g / 2.5);
        vec3 h = vc_h3(cell.x + 500.0, cell.y + 50.0, mod(zb + float(j), 800.0));
        if (h.x > dens) continue;
        vec2 cp = (cell + 0.15 + 0.7 * h.yz) * 2.5;
        vec2 dd = g - cp;
        float ws = max(0.03, t * pix * 1.2);
        float ws2 = ws * ws;
        float fade = smoothstep(0.8, 6.0, t) * (1.0 - smoothstep(30.0, 60.0, t));
        acc += mix(vc_c(5, K.x), vc_c(7, K.x), step(0.65, h.y)) * (0.0009 / ws2) * exp(-dot(dd, dd) / ws2) * fade * 2.5;
    }
    return acc;
}

vec3 vc_fog(vec4 K, vec3 col, vec3 ro, vec3 rd, float t, float dens) {
    float a = dens * 0.0035;
    float hd = dens * 0.01;
    float H = 14.0;
    float k = rd.y / H;
    float hf = abs(k) > 1e-4 ? hd * exp(-ro.y / H) * (1.0 - exp(-k * t)) / k : hd * exp(-ro.y / H) * t;
    float tau = a * t + hf;
    float sd = max(dot(rd, vec3(0.0, 0.0349, 0.9994)), 0.0);
    vec3 fc = vc_c(6, K.x) + vc_c(2, K.x) * 0.55 * pow(sd, 6.0) + vc_c(5, K.x) * 0.05 * K.z;
    return mix(col, fc, 1.0 - exp(-tau));
}

vec4 vectionCity(vec2 uv, sampler2D state, float time, float intensity, float illusion, float palette, float fog, float pulse, float bass, float music) {
    // the beat pulse fades in as the beat tracker locks (u_beatConfidence: 1 with the metronome)
    pulse *= clamp(u_beatConfidence, 0.0, 1.0);
    vec4 K = vec4(palette, clamp(illusion * intensity, 0.0, 1.0), 1.0 + 0.45 * pulse, 1.0 + 0.15 * bass);

    vec4 s0 = texelFetch(state, ivec2(0, 0), 0);
    vec4 s2 = texelFetch(state, ivec2(2, 0), 0);
    vec4 s3 = texelFetch(state, ivec2(3, 0), 0);
    bool ok = s0.x > 0.0;
    vec3 ro = ok ? vec3(s2.x, s2.y, s0.y) : vec3(vc_curve(0.0), 9.5, 0.0);
    float yaw = ok ? s3.x : 0.0;
    float pitch = ok ? s3.y : -0.06;
    float roll = ok ? s2.w : 0.0;

    vec3 F = vec3(sin(yaw) * cos(pitch), sin(pitch), cos(yaw) * cos(pitch));
    vec3 R = normalize(cross(vec3(0.0, 1.0, 0.0), F));
    vec3 U = cross(F, R);
    float cr = cos(roll);
    float sr = sin(roll);
    vec3 R2 = cr * R - sr * U;
    vec3 U2 = cr * U + sr * R;
    vec3 rd = normalize(uv.x * R2 + uv.y * U2 + 1.2 * F);
    float pix = 2.0 / (u_resolution.y * 1.2);

    float tF = rd.y < -1e-4 ? -ro.y / rd.y : 1e5;
    float tMax = min(tF, 650.0);
    vec3 n;
    vec4 m;
    float t = vc_trace(ro, rd, tMax, 56, 30, n, m);
    vec3 col;
    float near = 0.0;
    if (m.x >= 0.0) {
        vec3 p = ro + rd * t;
        col = vc_facade(K, p, rd, n, m, t, pix, time, false);
        col = vc_fog(K, col, ro, rd, t, fog);
        near = 18.0 / (18.0 + t);
    } else if (tF < 650.0) {
        t = tF;
        vec3 q = ro + rd * t;
        float wet;
        col = vc_street(K, q, rd, t, pix, wet);
        // wet reflection: trace the mirrored ray back into the canyon
        vec2 rp = vec2(vc_noise(q.xz * vec2(0.5, 0.25), 1200.0), vc_noise(q.xz * vec2(0.5, 0.25) + 5.7, 1200.0)) - 0.5;
        vec3 nr = normalize(vec3(rp.x * 0.012, 1.0, rp.y * 0.02));
        vec3 rr = reflect(rd, nr);
        rr.y = max(rr.y, 0.002);
        vec3 qr = q + vec3(0.0, 0.01, 0.0);
        vec3 nR;
        vec4 mR;
        float tR = vc_trace(qr, rr, 380.0, 32, 16, nR, mR);
        vec3 rc;
        if (mR.x >= 0.0) {
            rc = vc_facade(K, qr + rr * tR, rr, nR, mR, tR + t, pix, time, true);
            rc = vc_fog(K, rc, qr, rr, tR, fog);
        } else {
            rc = vc_sky(K, rr, qr, time, false);
            tR = 380.0;
        }
        rc += vc_lamps(K, qr, rr, tR, pix, 8);
        float cosv = max(-rd.y, 0.0);
        float fres = 0.04 + 0.96 * pow(1.0 - cosv, 5.0);
        col = mix(col, rc, clamp((0.08 + fres) * wet, 0.0, 0.95));
        col = vc_fog(K, col, ro, rd, t, fog);
        near = 18.0 / (18.0 + t);
    } else {
        col = vc_sky(K, rd, ro, time, true);
        t = 650.0;
        col = mix(col, vc_c(6, K.x) + vc_c(2, K.x) * 0.5 * pow(max(dot(rd, vec3(0.0, 0.0349, 0.9994)), 0.0), 6.0), (1.0 - exp(-fog * 0.6)) * exp(-max(rd.y, 0.0) * 9.0));
    }
    col += vc_lamps(K, ro, rd, t, pix, 16);
    col += vc_motes(K, ro, rd, t, pix, 0.16 + 0.12 * music * u_high) * (1.0 + 0.5 * pulse);
    return vec4(max(col, 0.0), near);
}

VectionLens.customGLSL:
// @node vectionLens
// @title Vection Lens
// @category effect
// @input uv "UV" default="gl_FragCoord.xy / u_resolution"
// @description Speed lens for the HDR frame: a radial motion blur that streaks everything away from the focus of expansion (read from the Vection Motion state), longer for near surfaces (frame alpha = nearness), in the periphery and at higher speed, combined with chromatic aberration that grows toward the frame edges. blur = streak length, aberration = edge fringing.
vec3 vectionLens(sampler2D frame, sampler2D state, vec2 uv, float blur, float aberration, float intensity) {
    vec4 s3 = texelFetch(state, ivec2(3, 0), 0);
    vec4 s4 = texelFetch(state, ivec2(4, 0), 0);
    vec2 ts = vec2(textureSize(frame, 0));
    float aspect = ts.x / ts.y;
    vec2 foe = clamp(vec2(0.5) + s3.zw * 1.2 * vec2(0.5 / aspect, 0.5), vec2(0.1), vec2(0.9));
    vec2 dv = uv - foe;
    float r = length(dv * vec2(aspect, 1.0));
    float near = texture(frame, uv).a;
    float amt = blur * (0.4 + 0.6 * clamp(intensity, 0.0, 1.5)) * clamp(s4.x, 0.0, 2.0) * smoothstep(0.12, 0.9, r) * (0.3 + 0.7 * near);
    vec2 rc = (uv - 0.5) * vec2(aspect, 1.0);
    vec2 ca = (uv - 0.5) * aberration * 0.012 * dot(rc, rc);
    vec3 acc = vec3(0.0);
    float wsum = 0.0;
    for (int i = 0; i < 10; i++) {
        float f = float(i) / 9.0;
        float w = 1.0 - 0.65 * f;
        vec2 o = uv - dv * amt * f;
        acc.r += texture(frame, o + ca).r * w;
        acc.g += texture(frame, o).g * w;
        acc.b += texture(frame, o - ca).b * w;
        wsum += w;
    }
    return acc / wsum;
}

LensStreak.customGLSL:
// @node lensStreak
// @title Lens Streak
// @category effect
// @input uv "UV" default="gl_FragCoord.xy / u_resolution"
// @description Wide horizontal anamorphic lens streak: blurs a bright-pass texture along x only (width in UV units, 33 taps, Gaussian weights).
vec3 lensStreak(sampler2D tex, vec2 uv, float width) {
    vec3 acc = vec3(0.0);
    float wsum = 0.0;
    for (int i = -16; i <= 16; i++) {
        float x = float(i) / 16.0;
        float wt = exp(-x * x * 4.0);
        acc += texture(tex, uv + vec2(x * width, 0.0)).rgb * wt;
        wsum += wt;
    }
    return acc / wsum;
}
